pub fn adaptive_sort<T: Ord + Clone>(arr: &mut [T]) {
    let n = arr.len();
    if n <= 1 { return; }
    if arr.windows(2).all(|w| w[0] <= w[1]) { return; }
    if arr.windows(2).all(|w| w[0] >= w[1]) { arr.reverse(); return; }
    let max_depth = (2.0 * (n as f64).log2()) as usize;
    isort(arr, max_depth);
}

fn isort<T: Ord + Clone>(arr: &mut [T], depth: usize) {
    let n = arr.len();
    if n <= 16 {
        for i in 1..n {
            let mut j = i;
            while j > 0 && arr[j - 1] > arr[j] { arr.swap(j, j - 1); j -= 1; }
        }
        return;
    }
    if depth == 0 { heapsort(arr); return; }
    let (lo, mid, hi) = (0, n / 2, n - 1);
    if arr[mid] < arr[lo] { arr.swap(lo, mid); }
    if arr[hi] < arr[lo] { arr.swap(lo, hi); }
    if arr[mid] < arr[hi] { arr.swap(mid, hi); }
    let pivot = arr[hi].clone();
    let mut i = 0;
    for j in 0..hi {
        if arr[j] <= pivot { arr.swap(i, j); i += 1; }
    }
    arr.swap(i, hi);
    isort(&mut arr[..i], depth - 1);
    if i + 1 < n { isort(&mut arr[i + 1..], depth - 1); }
}

fn heapsort<T: Ord>(a: &mut [T]) {
    let n = a.len();
    for i in (0..n / 2).rev() { sift(a, i, n); }
    for i in (1..n).rev() { a.swap(0, i); sift(a, 0, i); }
}

fn sift<T: Ord>(a: &mut [T], mut i: usize, n: usize) {
    loop {
        let mut c = 2 * i + 1;
        if c >= n { break; }
        if c + 1 < n && a[c] < a[c + 1] { c += 1; }
        if a[i] >= a[c] { break; }
        a.swap(i, c); i = c;
    }
}
